def max_juice_drunk(n, moves):
    vasya_turns = [i+1 for i in range(1, len(moves)+1) if i % n == 0]
    juice_count = 0
    for turn in vasya_turns:
        if turn >= 4:
            previous_moves = moves[turn-4:turn]
            if previous_moves.count('a') == 3 and previous_moves[2] == 'a':
                juice_count += 1
            elif previous_moves.count('b') == 3 and previous_moves[2] == 'b':
                juice_count += 1
    return juice_count

# Example usage
print(max_juice_drunk(4, 'abbba'))  # Output: 1
print(max_juice_drunk(4, 'abbab'))  # Output: 0

def max_juice_drunk(n, moves):
    optimal_moves = [''] * len(moves)
    for i in range(len(moves)):
        if i < 3:
            optimal_moves[i] = moves[i]
        else:
            if moves[i-3:i+1] == moves[i-4:i]:
                optimal_moves[i] = moves[i]
            else:
                optimal_moves[i] = moves[i].swapcase()
    return optimal_moves.count('b') if optimal_moves[-1] != 'b' else optimal_moves.count('b') - 1

